import org.jsoup.nodes.Attribute;
import org.jsoup.nodes.Attributes;
import org.junit.Assert;
import org.junit.Test;

import java.util.Iterator;

public class AttributesTest {

    @Test
    public void getValidKeyTest() {
        Attributes attributes = new Attributes();
        attributes.add("key", "value");
        Assert.assertEquals("value", attributes.get("key"));
    }

    @Test
    public void getNotExistKeyTest() {
        Assert.assertNull(new Attributes().get("notExistKey"));
    }

    @Test
    public void getIgnoreCaseValidKeyTest() {
        Attributes attributes = new Attributes();
        attributes.add("Key", "value");
        Assert.assertEquals("value", attributes.getIgnoreCase("key"));
    }

    @Test
    public void addStringKeyTest() {
        Attributes attributes = new Attributes();
        attributes.add("test", "value");
        Assert.assertEquals("value", attributes.get("test"));
    }

    @Test
    public void addBooleanKeyTest() {
        Attributes attributes = new Attributes();
        attributes.put("key", true);
        Assert.assertEquals("", attributes.get("key")); // Boolean value is not stored
    }

    @Test
    public void putAttributeTest() {
        Attributes attributes = new Attributes();
        Attribute attribute = new Attribute("key", "value");
        attributes.put(attribute);
        Assert.assertEquals("value", attributes.get("key"));
    }

    @Test
    public void removeTest() {
        Attributes attributes = new Attributes();
        attributes.add("key", "value");
        attributes.remove("key");
        Assert.assertNull(attributes.get("key"));
    }

    @Test
    public void hasKeyTest() {
        Attributes attributes = new Attributes();
        attributes.add("key", "value");
        Assert.assertTrue(attributes.hasKey("key"));
        Assert.assertFalse(attributes.hasKey("notExistKey"));
    }

    @Test
    public void sizeTest() {
        Attributes attributes = new Attributes();
        attributes.add("key1", "value1");
        attributes.add("key2", "value2");
        Assert.assertEquals(2, attributes.size());
    }

    @Test
    public void isEmptyTest() {
        Attributes attributes = new Attributes();
        Assert.assertTrue(attributes.isEmpty());
        attributes.add("key", "value");
        Assert.assertFalse(attributes.isEmpty());
    }

    @Test
    public void addAllTest() {
        Attributes attributes1 = new Attributes();
        attributes1.add("key1", "value1");

        Attributes attributes2 = new Attributes();
        attributes2.add("key2", "value2");

        attributes1.addAll(attributes2);

        Assert.assertEquals("value1", attributes1.get("key1"));
        Assert.assertEquals("value2", attributes1.get("key2"));
    }

    @Test
    public void iteratorTest() {
        Attributes attributes = new Attributes();
        Attribute attribute1 = new Attribute("key1", "value1");
        Attribute attribute2 = new Attribute("key2", "value2");
        attributes.put(attribute1);
        attributes.put(attribute2);

        Iterator<Attribute> iterator = attributes.iterator();
        Assert.assertTrue(iterator.hasNext());
        Assert.assertEquals(attribute1, iterator.next());
        Assert.assertTrue(iterator.hasNext());
        Assert.assertEquals(attribute2, iterator.next());
        Assert.assertFalse(iterator.hasNext());
    }
}
